      "$schema": "http://json-schema.org/draft-07/schema#",
      "description": "Form 2122 Schema",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "serviceOrganization"
      ],
      "properties": {
        "veteran": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "address"
          ],
          "properties": {
            "address": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "numberAndStreet",
                "city",
                "country"
              ],
              "allOf": [
                {
                  "if": {
                    "properties": {
                      "country": {
                        "const": "US"
                      }
                    }
                  },
                  "then": {
                    "required": [
                      "zipFirstFive"
                    ]
                  }
                }
              ],
              "properties": {
                "numberAndStreet": {
                  "description": "Street address with number and name.",
                  "type": "string",
                  "pattern": "^([-a-zA-Z0-9'.,&#]([-a-zA-Z0-9'.,&# ])?)+$",
                  "maxLength": 30
                },
                "aptUnitNumber": {
                  "oneOf": [
                    {
                      "type": "integer"
                    },
                    {
                      "type": "string"
                    }
                  ]
                },
                "city": {
                  "description": "City for the address.",
                  "type": "string",
                  "example": "Portland"
                },
                "state": {
                  "description": "State or province for the address.",
                  "type": "string",
                  "example": "OR"
                },
                "country": {
                  "description": "Country of the address.",
                  "type": "string",
                  "example": "US"
                },
                "zipFirstFive": {
                  "description": "Zip code (First 5 digits) of the address. Required if country is 'US'.",
                  "type": "string",
                  "pattern": "^\\d{5}?$",
                  "example": "12345"
                },
                "zipLastFour": {
                  "description": "Zip code (Last 4 digits) of the address.",
                  "type": "string",
                  "pattern": "^\\d{4}?$",
                  "example": "6789"
                }
              }
            },
            "phone": {
              "$comment": "the phone fields must not exceed 20 chars, when concatenated",
              "type": "object",
              "additionalProperties": false,
              "required": [
                "phoneNumber"
              ],
              "properties": {
                "countryCode": {
                  "description": "Country code of the phone number. Required for international phone numbers.",
                  "type": "string",
                  "pattern": "^[0-9]+$"
                },
                "areaCode": {
                  "description": "Area code of the phone number. Required if countryCode is '1' or not included.",
                  "type": "string",
                  "pattern": "^[2-9][0-9]{2}$",
                  "example": "555"
                },
                "phoneNumber": {
                  "description": "Phone number.",
                  "type": "string",
                  "pattern": "^[0-9]{1,14}$",
                  "example": "5555555"
                },
                "phoneNumberExt": {
                  "type": "string",
                  "pattern": "^[a-zA-Z0-9]{1,10}$"
                }
              },
              "if": {
                "properties": {
                  "countryCode": {
                    "anyOf": [
                      {
                        "type": "string",
                        "enum": [
                          "1"
                        ]
                      }
                    ]
                  }
                }
              },
              "then": {
                "required": [
                  "areaCode"
                ]
              },
              "else": {
                "anyOf": [
                  {
                    "required": [
                      "countryCode"
                    ]
                  },
                  {
                    "required": [
                      "areaCode"
                    ]
                  }
                ]
              }
            },
            "email": {
              "description": "Email address of the veteran.",
              "type": "string",
              "pattern": ".@.",
              "maxLength": 61,
              "example": "veteran@example.com"
            },
            "serviceBranch": {
              "description": "Service Branch for the veteran.",
              "type": "string",
              "enum": [
                "AIR FORCE",
                "ARMY",
                "COAST GUARD",
                "MARINE CORPS",
                "NAVY",
                "SPACE FORCE",
                "OTHER"
              ],
              "example": "ARMY"
            },
            "serviceBranchOther": {
              "description": "For a 'service branch' of value 'other', please provide the service branch name.",
              "type": "string",
              "maxLength": 50,
              "example": "Air National Guard"
            }
          }
        },
        "claimant": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "firstName",
            "lastName",
            "address",
            "relationship"
          ],
          "properties": {
            "firstName": {
              "description": "First name of Claimant.",
              "type": "string",
              "example": "John"
            },
            "middleInitial": {
              "description": "Middle initial of Claimant.",
              "type": "string",
              "example": "M"
            },
            "lastName": {
              "description": "Last name of Claimant.",
              "type": "string",
              "example": "Dow"
            },
            "address": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "numberAndStreet",
                "city",
                "country"
              ],
              "allOf": [
                {
                  "if": {
                    "properties": {
                      "country": {
                        "const": "US"
                      }
                    }
                  },
                  "then": {
                    "required": [
                      "zipFirstFive"
                    ]
                  }
                }
              ],
              "properties": {
                "numberAndStreet": {
                  "description": "Street address with number and name.",
                  "type": "string",
                  "pattern": "^([-a-zA-Z0-9'.,&#]([-a-zA-Z0-9'.,&# ])?)+$",
                  "maxLength": 30
                },
                "aptUnitNumber": {
                  "oneOf": [
                    {
                      "type": "integer"
                    },
                    {
                      "type": "string"
                    }
                  ]
                },
                "city": {
                  "description": "City for the address.",
                  "type": "string",
                  "example": "Portland"
                },
                "state": {
                  "description": "State or province for the address.",
                  "type": "string",
                  "example": "OR"
                },
                "country": {
                  "description": "Country of the address.",
                  "type": "string",
                  "example": "US"
                },
                "zipFirstFive": {
                  "description": "Zip code (First 5 digits) of the address. Required if country is 'US'.",
                  "type": "string",
                  "pattern": "^\\d{5}?$",
                  "example": "12345"
                },
                "zipLastFour": {
                  "description": "Zip code (Last 4 digits) of the address.",
                  "type": "string",
                  "pattern": "^\\d{4}?$",
                  "example": "6789"
                },
                "additionalProperties": {
                  "type": "boolean"
                }
              }
            },
            "phone": {
              "$comment": "the phone fields must not exceed 20 chars, when concatenated",
              "type": "object",
              "additionalProperties": false,
              "required": [
                "phoneNumber"
              ],
              "properties": {
                "countryCode": {
                  "description": "Country code of the phone number. Required for international phone numbers.",
                  "type": "string",
                  "pattern": "^[0-9]+$"
                },
                "areaCode": {
                  "description": "Area code of the phone number. Required if countryCode is '1' or not included.",
                  "type": "string",
                  "pattern": "^[2-9][0-9]{2}$",
                  "example": "555"
                },
                "phoneNumber": {
                  "description": "Phone number.",
                  "type": "string",
                  "pattern": "^[0-9]{1,14}$",
                  "example": "5555555"
                },
                "phoneNumberExt": {
                  "type": "string",
                  "pattern": "^[a-zA-Z0-9]{1,10}$"
                }
              },
              "if": {
                "properties": {
                  "countryCode": {
                    "anyOf": [
                      {
                        "type": "string",
                        "enum": [
                          "1"
                        ]
                      }
                    ]
                  }
                }
              },
              "then": {
                "required": [
                  "areaCode"
                ]
              },
              "else": {
